/// <summary>
/// Extension of the PurchLine table for the AAXPOCloseHelper model.
/// Provides a stub method for Landed Cost (ITM) ship line update integration
/// that can be enabled when the ITM module is present.
/// </summary>
[ExtensionOf(tableStr(PurchLine))]
final class PurchLine_AAXPOCloseHelper_Extension
{
}

Method.Source:
/// <summary>
